<?php require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../config/config.php';checkSession();if(!checkPermission('materiales')){header('Location: '.BASE_URL.'/index.php');exit();}if(empty($_SESSION['csrf_materiales']))$_SESSION['csrf_materiales']=bin2hex(random_bytes(32));$msg='';if($_SERVER['REQUEST_METHOD']==='POST'&&hash_equals($_SESSION['csrf_materiales'],$_POST['csrf']??'')){try{$id=(int)$_POST['id'];$qty=(int)$_POST['cantidad'];if($qty<1)throw new Exception();executeQuery('UPDATE inventario SET cantidad=GREATEST(0,cantidad-?) WHERE id_inventario=? AND es_gastable=1',[$qty,$id]);executeQuery("INSERT INTO movimientos_inventario(id_inventario,id_usuario,tipo_movimiento,cantidad,motivo) VALUES(?,?,'salida',?,?)",[$id,(int)$_SESSION['user_id'],$qty,trim($_POST['motivo'])?:'Uso clínico reportado']);$msg='Uso de material registrado.';}catch(Throwable $e){$msg='No fue posible registrar el uso.';}}$items=getRecords("SELECT id_inventario,nombre_producto,cantidad,cantidad_minima FROM inventario WHERE estado='activo' AND es_gastable=1 ORDER BY nombre_producto");include __DIR__.'/../includes/header.php';?><div class="page-header"><h1>Uso y solicitud de materiales</h1><p>Reporte el material gastable utilizado; el sistema alertará cuando deba reponerse.</p></div><div class="alert alert-info">Los doctores registran el consumo clínico. Administración y Contabilidad gestionan las compras de reposición.</div><?php if($msg):?><div class="alert alert-success"><?=displayText($msg)?></div><?php endif;?><section class="content-section"><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?=htmlspecialchars($_SESSION['csrf_materiales'])?>"><div class="form-group"><label>Material gastable</label><select class="form-control" name="id"><?php foreach($items as $i):?><option value="<?=$i['id_inventario']?>"><?=displayText($i['nombre_producto'])?> — Disponible: <?=$i['cantidad']?></option><?php endforeach;?></select></div><div class="form-group"><label>Cantidad utilizada</label><input class="form-control" type="number" name="cantidad" min="1" required></div><div class="form-group"><label>Motivo / consulta</label><input class="form-control" name="motivo"></div><button class="btn btn-primary">Reportar uso</button></form></section><section class="content-section mt-20"><h2>Materiales por reponer</h2><div class="table-responsive"><table class="table"><thead><tr><th>Material</th><th>Disponible</th><th>Mínimo</th></tr></thead><tbody><?php foreach($items as $i)if($i['cantidad']<=$i['cantidad_minima']):?><tr><td><?=displayText($i['nombre_producto'])?></td><td><?=$i['cantidad']?></td><td><?=$i['cantidad_minima']?></td></tr><?php endif;?></tbody></table></div></section><style>.content-section{background:#fff;padding:20px;border-radius:8px;box-shadow:var(--box-shadow)}.form-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:15px}@media(max-width:600px){.form-grid{grid-template-columns:1fr}}</style><?php include __DIR__.'/../includes/footer.php';?>
